import { effectiveAgent, type AttemptView, type TaskStatus, type TaskView } from "@/lib/agent-task-types"
import type { Quantity } from "@/lib/quantity"

interface TaskFilters {
  project?: string
  profile?: string
  model?: string
  query?: string
}

interface ColumnConfig {
  status: TaskStatus
  hidden?: boolean
  collapsed?: boolean
}

interface StatusColumn {
  status: TaskStatus
  tasks: TaskView[]
  collapsed: boolean
  /** Only on the `todo` column. */
  groups?: { ready: TaskView[]; waiting: TaskView[] }
}

interface FilterOptions {
  projects: string[]
  profiles: string[]
  models: string[]
}

type SortKey = "id" | "title" | "status" | "updatedAt" | "attempts" | "cost"
type SortDirection = "ascending" | "descending"

interface BoardSummary {
  total: number
  byStatus: Record<TaskStatus, number>
  /** `rated` counts tasks whose `acceptedFirstPass` is known. */
  acceptedFirstPass: { accepted: number; rated: number }
  cost: Quantity
  awaitingDecision: number
}

const TASK_STATUSES: readonly TaskStatus[] = ["proposed", "todo", "working", "review", "blocked", "done", "cancelled"]
const HIDDEN_BY_DEFAULT: ReadonlySet<TaskStatus> = new Set(["cancelled"])
const UNKNOWN: Quantity = { value: null, quality: "unknown" }
const collator = new Intl.Collator(undefined, { numeric: true, sensitivity: "base" })

function taskModels(task: TaskView): Set<string> {
  return new Set(task.attempts.map((attempt) => effectiveAgent(attempt).model))
}

function filterTasks(tasks: readonly TaskView[], filters: TaskFilters = {}): TaskView[] {
  const query = filters.query?.trim().toLowerCase()
  return tasks.filter(
    (task) =>
      (!filters.project || task.project === filters.project) &&
      (!filters.profile || task.profile === filters.profile) &&
      (!filters.model || task.attempts.some((attempt) => effectiveAgent(attempt).model === filters.model)) &&
      (!query || [task.id, task.title, task.goal].some((text) => text?.toLowerCase().includes(query))),
  )
}

function isReady(task: TaskView): boolean {
  return task.ready ?? task.dependsOn.every((dependency) => dependency.status === "done")
}

function columnOrder(columns: readonly ColumnConfig[]): TaskStatus[] {
  const configured = columns.map((column) => column.status).filter((status) => TASK_STATUSES.includes(status))
  return [...new Set([...configured, ...TASK_STATUSES])]
}

function groupByStatus(tasks: readonly TaskView[], columns: readonly ColumnConfig[] = []): StatusColumn[] {
  const byStatus = new Map<TaskStatus, TaskView[]>(TASK_STATUSES.map((status) => [status, []]))
  for (const task of tasks) byStatus.get(task.status)?.push(task)
  const config = new Map(columns.map((column) => [column.status, column]))

  return columnOrder(columns)
    .filter((status) => !(config.get(status)?.hidden ?? HIDDEN_BY_DEFAULT.has(status)))
    .map((status) => {
      const list = byStatus.get(status) ?? []
      const column: StatusColumn = { status, tasks: list, collapsed: config.get(status)?.collapsed ?? false }
      if (status === "todo") {
        column.groups = { ready: list.filter(isReady), waiting: list.filter((task) => !isReady(task)) }
      }
      return column
    })
}

function sortedDistinct(values: Iterable<string | undefined>): string[] {
  return [...new Set([...values].filter((value): value is string => Boolean(value)))].toSorted(collator.compare)
}

function filterOptions(tasks: readonly TaskView[]): FilterOptions {
  return {
    projects: sortedDistinct(tasks.map((task) => task.project)),
    profiles: sortedDistinct(tasks.map((task) => task.profile)),
    models: sortedDistinct(tasks.flatMap((task) => [...taskModels(task)])),
  }
}

function knownValue(quantity: Quantity | undefined): number | null {
  if (!quantity || quantity.quality === "unknown" || quantity.value === null) return null
  return Number.isFinite(quantity.value) ? quantity.value : null
}

/** Unknown when every part is unknown; estimated when any part is estimated or missing, since the sum is then a floor. */
function sumQuantities(parts: readonly (Quantity | undefined)[]): Quantity {
  const known = parts.filter((part): part is Quantity => knownValue(part) !== null)
  if (known.length === 0) return UNKNOWN
  const value = known.reduce((total, part) => total + (part.value ?? 0), 0)
  if (known.length < parts.length || known.some((part) => part.quality === "estimated")) {
    return { value, quality: "estimated" }
  }
  if (known.length === 1 && known[0]) return { value, quality: known[0].quality }
  return { value, quality: "derived" }
}

function taskCost(task: TaskView): Quantity {
  if (task.usage) return task.usage.costUsd
  if (task.attempts.length === 0) return UNKNOWN
  return sumQuantities(task.attempts.map((attempt) => attempt.usage?.costUsd ?? UNKNOWN))
}

function attemptCount(task: TaskView): number {
  return task.counts?.attempts ?? task.attempts.length
}

/** The attempt `activeAttemptId` names, or else the latest one. */
function activeAttempt(task: TaskView): AttemptView | undefined {
  return task.attempts.find((attempt) => attempt.id === task.activeAttemptId) ?? task.attempts.at(-1)
}

const comparators: Record<Exclude<SortKey, "cost">, (a: TaskView, b: TaskView) => number> = {
  id: (a, b) => collator.compare(a.id, b.id),
  title: (a, b) => collator.compare(a.title, b.title),
  status: (a, b) => TASK_STATUSES.indexOf(a.status) - TASK_STATUSES.indexOf(b.status),
  updatedAt: (a, b) => Date.parse(a.updatedAt) - Date.parse(b.updatedAt),
  attempts: (a, b) => attemptCount(a) - attemptCount(b),
}

function sortTasks(tasks: readonly TaskView[], key: SortKey, direction: SortDirection = "ascending"): TaskView[] {
  const sign = direction === "ascending" ? 1 : -1
  if (key !== "cost") return tasks.toSorted((a, b) => sign * comparators[key](a, b))
  return tasks.toSorted((a, b) => {
    const left = knownValue(taskCost(a))
    const right = knownValue(taskCost(b))
    if (left === null || right === null) return left === right ? 0 : left === null ? 1 : -1
    return sign * (left - right)
  })
}

function hasRun(task: TaskView): boolean {
  return task.usage !== undefined || task.attempts.length > 0
}

function needsDecision(task: TaskView): boolean {
  return Boolean(task.decisionNeeded) || (task.status === "proposed" && task.analysisMode === "review")
}

function summarize(tasks: readonly TaskView[]): BoardSummary {
  const byStatus = Object.fromEntries(TASK_STATUSES.map((status) => [status, 0])) as Record<TaskStatus, number>
  let accepted = 0
  let rated = 0
  let awaitingDecision = 0
  for (const task of tasks) {
    byStatus[task.status] += 1
    if (task.acceptedFirstPass !== undefined) rated += 1
    if (task.acceptedFirstPass) accepted += 1
    if (needsDecision(task)) awaitingDecision += 1
  }
  return {
    total: tasks.length,
    byStatus,
    acceptedFirstPass: { accepted, rated },
    cost: sumQuantities(tasks.filter(hasRun).map(taskCost)),
    awaitingDecision,
  }
}

export {
  TASK_STATUSES,
  activeAttempt,
  attemptCount,
  filterOptions,
  filterTasks,
  groupByStatus,
  isReady,
  needsDecision,
  sortTasks,
  sumQuantities,
  summarize,
  taskCost,
}
export type { BoardSummary, ColumnConfig, FilterOptions, SortDirection, SortKey, StatusColumn, TaskFilters }

import {
  createChange,
  createController,
  definePrimitive,
  dispatch,
  type ChangeDetails,
  type ChangeOptions,
} from "@ui-sdk/core"

import { filterOptions, type TaskFilters } from "@/lib/agent-task-board-model"
import type { AttemptView, TaskView, ThreadRef } from "@/lib/agent-task-types"

type BoardView = "board" | "table"
type BoardMode = "snapshot" | "live"
type AgentApproval = "confirm" | "allow" | "deny"

type ViewChangeReason = "item-press" | "imperative"
type FiltersChangeReason = "item-press" | "input-change" | "clear-press" | "imperative"
type SelectReason = "item-press" | "close-press" | "escape-key" | "outside-press" | "imperative"
type OpenThreadReason = "item-press" | "link-press" | "imperative"

type AgentTaskBoardOptions = {
  tasks?: TaskView[]
  view?: BoardView
  defaultView?: BoardView
  onViewChange?: (view: BoardView, details: ChangeDetails<ViewChangeReason>) => void
  filters?: TaskFilters
  defaultFilters?: TaskFilters
  onFiltersChange?: (filters: TaskFilters, details: ChangeDetails<FiltersChangeReason>) => void
  selectedTaskId?: string | null
  defaultSelectedTaskId?: string | null
  /** The contract's `onSelectTask`; the root component maps one onto the other. */
  onSelectedTaskIdChange?: (id: string | null, details: ChangeDetails<SelectReason>) => void
  onOpenThread?: (thread: ThreadRef, details: ChangeDetails<OpenThreadReason> & { attemptId: string }) => void
  controller?: AgentTaskBoardController
}

interface AgentTaskBoardController {
  setView: (view: BoardView, options?: ChangeOptions<ViewChangeReason>) => boolean | undefined
  filter: (
    partial: Partial<Record<keyof TaskFilters, string | null>>,
    options?: ChangeOptions<FiltersChangeReason>,
  ) => boolean | undefined
  selectTask: (id: string | null, options?: ChangeOptions<SelectReason>) => boolean | undefined
  openThread: (attemptId: string, options?: ChangeOptions<OpenThreadReason>) => boolean | undefined
}

const FILTER_KEYS = ["project", "profile", "model", "query"] as const
const CHOICE_KEYS = { project: "projects", profile: "profiles", model: "models" } as const

function reasonOf<Reason extends string>(options: unknown): { reason: Reason | "imperative"; event?: Event } {
  if (typeof options !== "object" || options === null) return { reason: "imperative" }
  const { reason = "imperative", event } = options as ChangeOptions<Reason>
  return { reason, event: event instanceof Event ? event : undefined }
}

// The agent bridge passes action arguments unchecked, so every action validates its own.
function checkFilters(partial: unknown, current: TaskFilters, tasks: readonly TaskView[]): TaskFilters {
  if (typeof partial !== "object" || partial === null || Array.isArray(partial)) {
    throw new TypeError(`filter takes an object with any of: ${FILTER_KEYS.join(", ")}.`)
  }
  const choices = filterOptions(tasks)
  const next: TaskFilters = { ...current }
  for (const [key, value] of Object.entries(partial)) {
    if (!(FILTER_KEYS as readonly string[]).includes(key)) {
      throw new TypeError(`Unknown filter "${key}". Filters: ${FILTER_KEYS.join(", ")}.`)
    }
    const filterKey = key as keyof TaskFilters
    if (value === null || value === undefined || value === "") {
      delete next[filterKey]
      continue
    }
    if (typeof value !== "string") throw new TypeError(`Filter "${key}" takes text, or null to clear it.`)
    if (filterKey !== "query") {
      const allowed = choices[CHOICE_KEYS[filterKey]]
      if (!allowed.includes(value)) throw new RangeError(`No ${key} "${value}". Choices: ${allowed.join(", ")}.`)
    }
    next[filterKey] = value
  }
  return next
}

function findAttempt(tasks: readonly TaskView[], attemptId: string): AttemptView | undefined {
  for (const task of tasks) {
    const attempt = task.attempts.find((candidate) => candidate.id === attemptId)
    if (attempt) return attempt
  }
  return undefined
}

const agentTaskBoard = definePrimitive({
  name: "agent-task-board",
  options: {
    tasks: "list",
    view: "string",
    defaultView: "string",
    onViewChange: "callback",
    filters: "value",
    defaultFilters: "value",
    onFiltersChange: "callback",
    selectedTaskId: "value",
    defaultSelectedTaskId: "value",
    onSelectedTaskIdChange: "callback",
    onOpenThread: "callback",
    controller: "value",
  },
  state: (options: AgentTaskBoardOptions) => ({
    view: options.view ?? options.defaultView ?? ("board" as BoardView),
    filters: options.filters ?? options.defaultFilters ?? {},
    selectedTaskId:
      options.selectedTaskId !== undefined ? options.selectedTaskId : (options.defaultSelectedTaskId ?? null),
  }),
  sync: (options) => ({
    ...(options.view === undefined ? {} : { view: options.view }),
    ...(options.filters === undefined ? {} : { filters: options.filters }),
    ...(options.selectedTaskId === undefined ? {} : { selectedTaskId: options.selectedTaskId }),
  }),
  controlled: ["view", "filters", "selectedTaskId"],
  api: (context) => {
    const change = createChange(context)
    const tasks = () => context.options().tasks ?? []
    return {
      setView(view: unknown, options?: ChangeOptions<ViewChangeReason>) {
        if (view !== "board" && view !== "table") throw new TypeError(`setView takes "board" or "table".`)
        return change("view", view, reasonOf(options))
      },
      filter(partial: unknown, options?: ChangeOptions<FiltersChangeReason>) {
        const next = checkFilters(partial, context.store.get().filters, tasks())
        return change("filters", next, reasonOf(options))
      },
      selectTask(id: unknown, options?: ChangeOptions<SelectReason>) {
        if (id !== null && !tasks().some((task) => task.id === id)) {
          throw new RangeError(`No task "${String(id)}". Pass a task id from the board, or null to close it.`)
        }
        return change("selectedTaskId", id as string | null, reasonOf(options))
      },
      openThread(attemptId: unknown, options?: ChangeOptions<OpenThreadReason>) {
        const attempt = typeof attemptId === "string" ? findAttempt(tasks(), attemptId) : undefined
        if (!attempt) throw new RangeError(`No attempt "${String(attemptId)}" on the board.`)
        if (!attempt.thread) throw new RangeError(`Attempt "${attempt.id}" has no thread.`)
        if (!context.options().onOpenThread) throw new Error("This board doesn't open threads.")
        const details = { ...reasonOf(options), attemptId: attempt.id }
        return !dispatch(context, "onOpenThread", attempt.thread, details)
      },
      tasks: () => tasks().map((task) => ({ value: task.id, label: `${task.id} ${task.title}` })),
    }
  },
  slots: (slot) => ({
    root: slot({
      role: "region",
      attrs: (state) => ({ "data-view": state.view, "data-selected": state.selectedTaskId === null ? undefined : "" }),
    }),
  }),
  agent: { actions: ["selectTask", "openThread", "setView", "filter"], items: (api) => api.tasks() },
})

function createAgentTaskBoardController() {
  return createController<AgentTaskBoardController>()
}

export { agentTaskBoard, createAgentTaskBoardController }
export type { AgentApproval, AgentTaskBoardController, AgentTaskBoardOptions, BoardMode, BoardView }

import { definePrimitive, dispatch, type ChangeDetails, type ChangeOptions } from "@ui-sdk/core"

import type { TaskView } from "@/lib/agent-task-types"
import type { AgentApproval, BoardMode } from "@/components/ui/agent-task-board-primitive"

type ProposalReason = "item-press" | "imperative"
type ProposalAction = (id: string, details: ChangeDetails<ProposalReason>) => void | Promise<void>

type AgentTaskProposalsOptions = {
  tasks?: TaskView[]
  mode?: BoardMode
  agentApproval?: AgentApproval
  /** Required with `agentApproval` "confirm": what an agent asks a person before it approves or rejects. */
  agentConfirm?: string
  onApproveProposal?: ProposalAction
  onRejectProposal?: ProposalAction
}

type ProposalItem = { value: string; label: string }

function proposalsOf(tasks: readonly TaskView[] = []): ProposalItem[] {
  return tasks
    .filter((task) => task.status === "proposed")
    .map((task) => ({ value: task.id, label: `${task.id} ${task.title}` }))
}

function stateOf(options: AgentTaskProposalsOptions) {
  const approval = options.agentApproval ?? "confirm"
  const agentConfirm = approval === "confirm" ? options.agentConfirm || undefined : undefined
  // Without a sentence to show, "confirm" can't ask a person, so the actions stay hidden rather than run unasked.
  const askable = approval === "allow" || agentConfirm !== undefined
  const handled = Boolean(options.onApproveProposal || options.onRejectProposal)
  return {
    proposals: proposalsOf(options.tasks),
    available: options.mode === "live" && askable && handled,
    agentConfirm,
  }
}

// `dispatch` reports only whether the change was canceled; the callback's Promise is what lets the bridge report pending and failure.
function run(
  options: () => AgentTaskProposalsOptions,
  name: "onApproveProposal" | "onRejectProposal",
  id: string,
  details: ChangeOptions<ProposalReason>,
) {
  const callback = options()[name]
  let result: unknown
  const canceled = dispatch(
    {
      options: () => ({
        [name]: (value: string, given: ChangeDetails<ProposalReason>) => (result = callback?.(value, given)),
      }),
    },
    name,
    id,
    { reason: details.reason ?? "imperative", event: details.event },
  )
  return canceled ? false : (result ?? true)
}

const agentTaskProposals = definePrimitive({
  name: "agent-task-proposals",
  options: {
    tasks: "list",
    mode: "string",
    agentApproval: "string",
    agentConfirm: "string",
    onApproveProposal: "action",
    onRejectProposal: "action",
  },
  state: stateOf,
  sync: stateOf,
  api: (context) => {
    const act = (
      name: "onApproveProposal" | "onRejectProposal",
      id: unknown,
      options?: ChangeOptions<ProposalReason>,
    ) => {
      const state = context.store.get()
      if (!state.available || !context.options()[name]) throw new Error("Proposals can't be decided on this board now.")
      if (!state.proposals.some((proposal) => proposal.value === id)) {
        const ids = state.proposals.map((proposal) => proposal.value).join(", ") || "none"
        throw new RangeError(`No proposal "${String(id)}". Proposals: ${ids}.`)
      }
      return run(context.options, name, id as string, {
        reason: options?.reason ?? "imperative",
        event: options?.event,
      })
    }
    return {
      approveProposal: (id: unknown, options?: ChangeOptions<ProposalReason>) => act("onApproveProposal", id, options),
      rejectProposal: (id: unknown, options?: ChangeOptions<ProposalReason>) => act("onRejectProposal", id, options),
      proposals: () => context.store.get().proposals,
    }
  },
  slots: (slot) => ({
    root: slot({
      role: "group",
      attrs: (state) => ({
        "data-agent-confirm": state.agentConfirm,
        "data-available": state.available ? "" : undefined,
      }),
    }),
  }),
  agent: {
    actions: ["approveProposal", "rejectProposal"],
    items: (api) => api.proposals(),
    shown: (state) => state.available,
  },
})

export { agentTaskProposals }
export type { AgentTaskProposalsOptions, ProposalAction }

"use client"

import { createParts } from "@ui-sdk/react/primitive"
import type { ComponentProps } from "react"

import {
  agentTaskBoard,
  createAgentTaskBoardController,
  type AgentTaskBoardOptions,
} from "@/components/ui/agent-task-board-primitive"
import { agentTaskProposals } from "@/components/ui/agent-task-proposals-primitive"

const { Root: BoardRoot } = createParts(agentTaskBoard, { root: "div" })
const { Root: AgentTaskProposalsRoot } = createParts(agentTaskProposals, { root: "div" })

type AgentTaskBoardRootProps = Omit<ComponentProps<typeof BoardRoot>, "onSelectedTaskIdChange"> & {
  onSelectTask?: AgentTaskBoardOptions["onSelectedTaskIdChange"]
}

function AgentTaskBoardRoot({ onSelectTask, ...props }: AgentTaskBoardRootProps) {
  return <BoardRoot onSelectedTaskIdChange={onSelectTask} {...props} />
}

export { AgentTaskBoardRoot, AgentTaskProposalsRoot, createAgentTaskBoardController }
export type { AgentTaskBoardRootProps }
